const tk = (s) => (s.match(/@@[LC]\d+@@/g) || []).sort();
const out = src.map((o) => {
  let tr = T[o.line] !== undefined ? T[o.line] : o.masked;
  const a = tk(o.masked), b = tk(tr);
  if (a.length !== b.length || a.some((v, i) => v !== b[i])) {
    console.error("FALLBACK line", o.line, "src:", o.masked, "tr:", tr);
    tr = o.masked;
  }
  return { line: o.line, translated: tr };
});

writeFileSync(outPath, JSON.stringify(out, null, 2) + "\n");
console.log("batch_00 written:", out.length, "entries");
